<?php
defined( 'ABSPATH' ) || exit;

/**
 * NMKR Studio API v2 client.
 *
 * Docs:    https://docs.nmkr.io/nmkr-studio-api
 * Swagger: https://studio-api.nmkr.io/swagger (mainnet)
 *          https://studio-api.preprod.nmkr.io/swagger (preprod)
 *
 * Auth: Bearer token in Authorization header.
 * All UIDs (project, nft) are UUIDs generated by NMKR Studio.
 */
class BCH_NMKR {

    private string $api_key;
    private string $base_url;
    private string $project_uid;

    public function __construct() {
        $network           = (string) get_option( 'bch_network', 'preprod' );
        $this->api_key     = (string) get_option( 'bch_nmkr_api_key', '' );
        $this->project_uid = (string) get_option( 'bch_nmkr_project_uid', '' );

        $this->base_url = $network === 'mainnet'
            ? 'https://studio-api.nmkr.io/v2'
            : 'https://studio-api.preprod.nmkr.io/v2';
    }

    // -------------------------------------------------------------------------
    // NFT Upload
    // -------------------------------------------------------------------------

    /**
     * Upload a single CIP-68 NFT definition to the NMKR project.
     *
     * NMKR stores the NFT as "free" (not yet minted). Returns the nft_uid
     * used in subsequent MintAndSend calls.
     *
     * @param array $metadata  CIP-68 metadata map (name, image, event fields …)
     * @param string $token_name  On-chain token name (ASCII, max 32 chars)
     * @return string|WP_Error  nft_uid on success.
     */
    public function upload_nft( array $metadata, string $token_name ): string|WP_Error {
        // Flat body — no wrapper key. metadataPlaceholder must be an empty array.
        // fileFromIPFS only works with CIDv0 (Qm...) on NMKR's IPFS node.
        $body = [
            'tokenname'           => $token_name,
            'displayname'         => $metadata['name'] ?? $token_name,
            'description'         => $metadata['event_name'] ?? '',
            'metadataPlaceholder' => [],
            'previewImageNft'     => [
                'mimetype'     => 'image/png',
                'fileFromIPFS' => self::extract_ipfs_cid( $metadata['image'] ?? '' ),
            ],
            'metadata' => $metadata,
        ];

        $response = $this->post( "/UploadNft/{$this->project_uid}", $body );

        // 409 = token name already exists in NMKR — fetch its UID and reuse it
        if ( is_wp_error( $response ) ) {
            if ( str_contains( $response->get_error_message(), '409' ) ) {
                return $this->get_nft_uid_by_name( $token_name );
            }
            return $response;
        }

        $nft_uid = $response['nftUid'] ?? ( $response[0]['nftUid'] ?? null );
        if ( ! $nft_uid ) {
            return new WP_Error( 'nmkr_upload', 'Could not extract nftUid from NMKR response.' );
        }
        return (string) $nft_uid;
    }

    /**
     * Look up an NFT UID by its token name (used when a 409 is returned).
     *
     * Endpoint: GET /v2/GetNftDetails/{projectUID}/{tokenname}
     */
    public function get_nft_uid_by_name( string $token_name ): string|WP_Error {
        $response = $this->get( "/GetNftDetails/{$this->project_uid}/{$token_name}" );
        if ( is_wp_error( $response ) ) {
            return $response;
        }
        $nft_uid = $response['nftUid'] ?? null;
        if ( ! $nft_uid ) {
            return new WP_Error( 'nmkr_lookup', "Could not find NFT UID for token name: {$token_name}" );
        }
        return (string) $nft_uid;
    }

    // -------------------------------------------------------------------------
    // Mint & Send
    // -------------------------------------------------------------------------

    /**
     * Mint a specific (already-uploaded) NFT and send it to a wallet address.
     *
     * Endpoint: GET /v2/MintAndSendSpecific/{projectUID}/{nftUID}/{count}/{walletAddress}
     *
     * @return array|WP_Error  Response containing mintAndSendId on success.
     */
    public function mint_and_send( string $nft_uid, string $wallet_address, int $count = 1 ): array|WP_Error {
        $path = "/MintAndSendSpecific/{$this->project_uid}/{$nft_uid}/{$count}/" . rawurlencode( $wallet_address );
        return $this->get( $path );
    }

    /**
     * Check the current state of an NFT (free / reserved / minted).
     *
     * Endpoint: GET /v2/GetNftDetailsById/{projectUID}/{nftUID}
     *
     * @return array|WP_Error
     */
    public function get_nft_details( string $nft_uid ): array|WP_Error {
        return $this->get( "/GetNftDetailsById/{$this->project_uid}/{$nft_uid}" );
    }

    /**
     * Get counts of free / reserved / minted tokens for the project.
     *
     * Endpoint: GET /v2/GetCounts/{projectUID}
     *
     * @return array|WP_Error
     */
    public function get_counts(): array|WP_Error {
        return $this->get( "/GetCounts/{$this->project_uid}" );
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    /**
     * Extract bare IPFS CID from any of these formats:
     *   ipfs://QmXxx...
     *   ipfs://bafkrei...
     *   https://gateway.io/ipfs/QmXxx...
     *   QmXxx... (bare CID)
     * Falls back to a known placeholder if empty.
     */
    private static function extract_ipfs_cid( string $image ): string {
        // CIDv0 starts with Qm (base58, 46 chars) — supported by NMKR's IPFS node.
        // CIDv1 starts with baf/bag/b (base32) — NMKR cannot fetch these; use fallback.
        $fallback = 'QmUFPkMQMiCCRMoSUCDFkJKnfv8nfCwRMh3RrDaZQiQkv4';

        if ( empty( $image ) || $image === 'ipfs://QmPlaceholder' ) {
            return $fallback;
        }

        // Extract CID from gateway URL: https://gateway/ipfs/{CID}
        if ( preg_match( '#/ipfs/([a-zA-Z0-9]+)#', $image, $m ) ) {
            $cid = $m[1];
        } elseif ( str_starts_with( $image, 'ipfs://' ) ) {
            $cid = substr( $image, 7 );
        } else {
            $cid = $image;
        }

        // CIDv1 (baf...) not supported by NMKR — fall back to placeholder
        if ( ! str_starts_with( $cid, 'Qm' ) ) {
            return $fallback;
        }

        return $cid;
    }

    // -------------------------------------------------------------------------
    // HTTP helpers
    // -------------------------------------------------------------------------

    private function get( string $path ): array|WP_Error {
        $response = wp_remote_get(
            $this->base_url . $path,
            [
                'headers' => $this->headers(),
                'timeout' => 30,
            ]
        );
        return $this->parse( $response );
    }

    private function post( string $path, array $body ): array|WP_Error {
        $response = wp_remote_post(
            $this->base_url . $path,
            [
                'headers' => $this->headers(),
                'body'    => wp_json_encode( $body ),
                'timeout' => 30,
            ]
        );
        return $this->parse( $response );
    }

    private function headers(): array {
        return [
            'Authorization' => 'Bearer ' . $this->api_key,
            'Content-Type'  => 'application/json',
            'accept'        => 'text/plain',
        ];
    }

    private function parse( array|WP_Error $response ): array|WP_Error {
        if ( is_wp_error( $response ) ) {
            return $response;
        }
        $code = wp_remote_retrieve_response_code( $response );
        $body = wp_remote_retrieve_body( $response );
        $data = json_decode( $body, true );

        // NMKR returns plain string on some endpoints (e.g. mint-and-send IDs)
        if ( $data === null && $body !== '' ) {
            $data = [ 'raw' => trim( $body, '"' ) ];
        }

        if ( $code >= 400 ) {
            $msg = is_array( $data ) ? ( $data['errorMessage'] ?? $body ) : $body;
            return new WP_Error( 'nmkr_error', "[{$code}] {$msg}" );
        }
        return is_array( $data ) ? $data : [ 'raw' => $data ];
    }
}
